<template>
	<!--
	  Child table `units` (Request AYDA Motor Item) sebagai kartu collapsible.
	  1 baris child = 1 kartu. Kartu bisa dibuka/tutup. Mode `editable`:
	  pilih Motor Tarikan (dropdown terfilter cabang) → field lain terisi otomatis
	  (fetch_from). Mode baca: kartu hanya menampilkan isi.
	-->
	<div class="space-y-3">
		<div
			v-if="!rows.length"
			class="rounded-2xl border border-dashed border-ui-line-gray-300 bg-ui-surface-gray-50 px-4 py-8 text-center"
		>
			<p class="text-sm text-ui-ink-gray-400">Belum ada unit.</p>
			<button
				v-if="editable"
				type="button"
				class="mt-3 inline-flex items-center gap-1.5 rounded-full bg-primary px-4 py-2 text-sm font-semibold text-ui-onPrimary transition hover:opacity-90"
				@click="addRow"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-4 w-4"
					fill="none"
					stroke="currentColor"
					stroke-width="2.2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="M12 5v14" />
					<path d="M5 12h14" />
				</svg>
				Tambah Unit
			</button>
		</div>

		<div
			v-for="(row, idx) in rows"
			:key="row.__key || idx"
			class="overflow-hidden rounded-2xl border border-ui-line-gray-200 bg-ui-surface shadow-sm"
		>
			<!-- Header kartu (klik untuk buka/tutup) -->
			<button
				type="button"
				class="flex w-full items-center gap-3 px-4 py-3 text-left transition hover:bg-ui-surface-gray-50"
				@click="toggle(idx)"
			>
				<span
					class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-sm font-bold text-primary"
				>
					{{ idx + 1 }}
				</span>
				<span class="min-w-0 flex-1">
					<span class="block truncate text-sm font-semibold text-ui-ink-gray-900">
						{{ row.nama_nasabah || row.motor_tarikan || 'Unit baru' }}
					</span>
					<span class="block truncate text-xs text-ui-ink-gray-400">
						{{ row.nopol || row.no_perjanjian || 'Pilih Motor Tarikan…' }}
					</span>
				</span>
				<span
					v-if="row.sisa_pokok"
					class="shrink-0 text-right text-xs font-semibold text-ui-ink-gray-700"
				>
					{{ currencyDisplay(row.sisa_pokok) }}
				</span>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5 shrink-0 text-ui-ink-gray-400 transition-transform"
					:class="{ 'rotate-180': isOpen(idx) }"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="m6 9 6 6 6-6" />
				</svg>
			</button>

			<!-- Body kartu -->
			<div v-if="isOpen(idx)" class="border-t border-ui-line-gray-100 px-4 py-4">
				<div class="space-y-3">
					<div v-for="f in childFields" :key="f.fieldname">
						<label class="mb-1 block text-xs font-medium text-ui-ink-gray-500">
							{{ f.label }}
							<span v-if="f.reqd && editable" class="text-ui-ink-red-500">*</span>
						</label>

						<!-- motor_tarikan → dropdown searchable (hanya editable) -->
						<div v-if="f.fieldname === 'motor_tarikan' && editable" class="relative">
							<button
								type="button"
								:class="[
									inputClass,
									'flex items-center justify-between gap-2 text-left',
								]"
								@click="toggleDropdown(idx)"
							>
								<span class="min-w-0 truncate font-bold text-ui-ink-gray-900">
									{{ row.motor_tarikan || 'Pilih…' }}
								</span>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
									fill="none"
									stroke="currentColor"
									stroke-width="2"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="m6 9 6 6 6-6" />
								</svg>
							</button>

							<div
								v-if="openDropdown === idx"
								class="absolute left-0 right-0 z-30 mt-1.5 overflow-hidden rounded-xl border border-ui-line-gray-200 bg-ui-surface shadow-xl ring-1 ring-black/5"
							>
								<div class="border-b border-ui-line-gray-100 p-2">
									<input
										v-model="search"
										type="text"
										placeholder="Cari unit…"
										:class="inputClass"
										@click.stop
										@input="onSearch(idx)"
									/>
								</div>
								<div class="max-h-56 overflow-y-auto p-1">
									<button
										v-for="opt in results"
										:key="opt"
										type="button"
										class="flex w-full items-start rounded-lg px-3 py-2 text-left font-bold text-ui-ink-gray-900 transition hover:bg-ui-surface-gray-50"
										@click="pickMotor(idx, opt)"
									>
										{{ opt }}
									</button>
									<p
										v-if="!results.length"
										class="px-3 py-2 text-xs text-ui-ink-gray-400"
									>
										{{ searchLoading ? 'Mencari…' : 'Tidak ada hasil' }}
									</p>
								</div>
							</div>
						</div>

						<!-- read-only / mode baca → teks -->
						<p
							v-else-if="f.fieldtype === 'Currency'"
							class="text-sm font-medium text-ui-ink-gray-900"
						>
							{{ currencyDisplay(row[f.fieldname]) || '—' }}
						</p>
						<p v-else-if="f.fieldtype === 'Date'" class="text-sm text-ui-ink-gray-800">
							{{ formatDateDisplay(row[f.fieldname]) || '—' }}
						</p>
						<p v-else class="break-words text-sm text-ui-ink-gray-800">
							{{
								row[f.fieldname] == null || row[f.fieldname] === ''
									? '—'
									: row[f.fieldname]
							}}
						</p>
					</div>
				</div>

				<button
					v-if="editable"
					type="button"
					class="mt-4 inline-flex items-center gap-1.5 rounded-lg border border-ui-line-red-200 px-3 py-2 text-xs font-semibold text-ui-ink-red-600 transition hover:bg-ui-surface-red-50"
					@click="removeRow(idx)"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-4 w-4"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="M3 6h18" />
						<path
							d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"
						/>
						<line x1="10" y1="11" x2="10" y2="17" />
						<line x1="14" y1="11" x2="14" y2="17" />
					</svg>
					Hapus unit ini
				</button>
			</div>
		</div>

		<!-- Tombol tambah unit (bawah, saat sudah ada baris) -->
		<button
			v-if="editable && rows.length"
			type="button"
			class="flex w-full items-center justify-center gap-1.5 rounded-2xl border border-dashed border-primary/50 bg-primary/5 py-3 text-sm font-semibold text-primary transition hover:bg-primary/10"
			@click="addRow"
		>
			<svg
				xmlns="http://www.w3.org/2000/svg"
				viewBox="0 0 24 24"
				class="h-4 w-4"
				fill="none"
				stroke="currentColor"
				stroke-width="2.2"
				stroke-linecap="round"
				stroke-linejoin="round"
			>
				<path d="M12 5v14" />
				<path d="M5 12h14" />
			</svg>
			Tambah Unit
		</button>

		<!-- Penutup dropdown saat klik di luar -->
		<div
			v-if="openDropdown !== null"
			class="fixed inset-0 z-20"
			@click="openDropdown = null"
		/>
	</div>
</template>

<script setup>
import { onMounted, ref, watch } from 'vue'
import { motorTarikanFilters } from '../data/requestAydaStatus'
import { notifyError } from '../composables/toast'

const props = defineProps({
	modelValue: { type: Array, default: () => [] },
	editable: { type: Boolean, default: false },
	cabang: { type: String, default: '' },
})
const emit = defineEmits(['update:modelValue'])

const inputClass =
	'min-h-[40px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-sm text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30'

// Baris child (v-model). Tambahkan __key unik supaya v-for stabil saat reorder.
let _key = 0
const rows = ref([])
function syncFromProp() {
	rows.value = (props.modelValue || []).map((r) => ({ __key: r.__key ?? ++_key, ...r }))
}
watch(() => props.modelValue, syncFromProp, { immediate: true })

function emitRows() {
	// Buang __key sebelum dikirim ke parent (bukan field dokumen).
	emit(
		'update:modelValue',
		rows.value.map(({ __key, ...rest }) => rest)
	)
}

// ---- Meta child doctype (field + fetch_from) ----
const childFields = ref([])
const CHILD = 'Request AYDA Motor Item'
async function loadChildMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(CHILD)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === CHILD) || docs[0]
		childFields.value = (dt.fields || []).filter(
			(f) =>
				!['Section Break', 'Column Break', 'HTML', 'Button', 'Table'].includes(
					f.fieldtype
				) && !f.hidden
		)
	} catch (e) {
		notifyError(e, 'Gagal memuat struktur unit')
	}
}
onMounted(loadChildMeta)

// ---- Buka/tutup kartu ----
const openSet = ref(new Set())
function isOpen(idx) {
	return openSet.value.has(idx)
}
function toggle(idx) {
	const s = new Set(openSet.value)
	s.has(idx) ? s.delete(idx) : s.add(idx)
	openSet.value = s
}

function addRow() {
	rows.value.push({ __key: ++_key })
	openSet.value = new Set([...openSet.value, rows.value.length - 1])
	emitRows()
}
function removeRow(idx) {
	rows.value.splice(idx, 1)
	openSet.value = new Set() // reset supaya indeks tidak salah geser
	emitRows()
}

// ---- Dropdown Motor Tarikan (per kartu) ----
const openDropdown = ref(null)
const search = ref('')
const results = ref([])
const searchLoading = ref(false)
let searchTimer = null

function toggleDropdown(idx) {
	if (openDropdown.value === idx) {
		openDropdown.value = null
		return
	}
	openDropdown.value = idx
	search.value = ''
	fetchResults('')
}

// Motor Tarikan yang SUDAH dipilih di baris lain → dikecualikan dari dropdown
// supaya tidak bisa dipilih dua kali (anti-duplikat). Baris yang dropdown-nya
// sedang dibuka tidak ikut dikecualikan agar nilainya sendiri tetap valid.
function usedMotorNames() {
	return rows.value
		.filter((r, i) => i !== openDropdown.value && r.motor_tarikan)
		.map((r) => String(r.motor_tarikan))
}

async function fetchResults(query) {
	searchLoading.value = true
	results.value = []
	try {
		const filters = [...motorTarikanFilters(props.cabang)]
		const used = usedMotorNames()
		if (used.length) filters.push(['name', 'not in', used])
		if (query) filters.push(['name', 'like', `%${query}%`])
		const params = new URLSearchParams({
			doctype: 'Motor Tarikan',
			fields: JSON.stringify(['name']),
			filters: JSON.stringify(filters),
			limit_page_length: '20',
			order_by: 'modified desc',
		})
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		if (!res.ok) throw new Error((json && json.exception) || `HTTP ${res.status}`)
		results.value = (json.message || []).map((r) => String(r.name))
	} catch (e) {
		results.value = []
		notifyError(e, 'Gagal memuat unit')
	} finally {
		searchLoading.value = false
	}
}
function onSearch() {
	clearTimeout(searchTimer)
	searchTimer = setTimeout(() => fetchResults(search.value.trim()), 300)
}

// Pilih unit → set motor_tarikan + fetch_from field turunannya.
async function pickMotor(idx, value) {
	rows.value[idx].motor_tarikan = value
	openDropdown.value = null
	await applyFetchFrom(idx, value)
	emitRows()
}

async function applyFetchFrom(idx, value) {
	const targets = childFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith('motor_tarikan.')
	)
	if (!value) {
		for (const t of targets) rows.value[idx][t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice('motor_tarikan.'.length))
	try {
		const params = new URLSearchParams({
			doctype: 'Motor Tarikan',
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice('motor_tarikan.'.length)
			if (src in data) rows.value[idx][t.fieldname] = data[src]
		}
	} catch (e) {
		/* fallback: server isi saat save */
	}
}

// ---- Format ----
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(Number(v))}`
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
</script>
